<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessageBox,ElMessage } from 'element-plus'
import { api,apiResult } from '../lib/api'
import { can,canGateway } from '../lib/auth'
import { dateTime,pretty,statusLabel } from '../lib/format'
import { enc,errorText,hasCapability,loadChoices,stableKey,type Row,type Page } from '../features/gateway/utils'
import ConfigurationEditor from '../features/gateway/ConfigurationEditor.vue'
import SimpleTaskForm from '../features/gateway/SimpleTaskForm.vue'
const route=useRoute(),router=useRouter(),pageId=computed(()=>String(route.meta.pageId)),loading=ref(false),saving=ref(false),error=ref(''),rows=ref<Row[]>([]),scopes=ref<Row[]>([]),next=ref(''),snapshot=ref(''),gateway=ref<Row>(),config=ref<Row>(),tasks=ref<Row[]>([]),tab=ref('overview')
const filter=reactive({groupId:'',state:'',search:''}),edit=ref(false),editId=ref(''),editEtag=ref(''),editForm=reactive({displayName:'',groupId:'',state:'ACTIVE'}),taskDialog=ref(false),importDialog=ref(false),importResult=ref<Row>(),importForm=reactive({artifactId:'',groupId:''}),importKey=stableKey(),formKey=stableKey()
const visibleRows=computed(()=>rows.value.filter(g=>!filter.search||[g.gatewayId,g.displayName,g.sn,g.model].join(' ').toLowerCase().includes(filter.search.toLowerCase())))
const groupOptions=computed(()=>scopes.value.filter(s=>s.kind==='GROUP'&&s.state!=='ARCHIVED'))
const tree=computed(()=>{const map=new Map<string,Row>();for(const s of scopes.value)map.set(s.scopeId,{...s,label:s.name,children:[]});const roots:Row[]=[];for(const s of map.values()){if(s.parentScopeId&&map.has(s.parentScopeId))map.get(s.parentScopeId)!.children.push(s);else roots.push(s)}return roots})
async function loadScopes(){if(can('scope:read'))scopes.value=await loadChoices('/api/v1/resource-scopes')}
let listEpoch=0
async function loadList(more=false){const epoch=++listEpoch;loading.value=true;error.value='';try{if(!more){rows.value=[];next.value=''}const q=new URLSearchParams({limit:'50'});if(filter.groupId)q.set('groupId',filter.groupId);if(filter.state)q.set('state',filter.state);if(more&&next.value)q.set('cursor',next.value);const p=await api<Page>('/api/v1/gateways?'+q);if(epoch!==listEpoch)return;rows.value=more?[...rows.value,...p.items]:p.items;next.value=p.nextCursor||'';snapshot.value=p.snapshotAt||''}catch(e){if(epoch===listEpoch)error.value=errorText(e)}finally{if(epoch===listEpoch)loading.value=false}}
let detailEpoch=0
async function loadDetail(){const epoch=++detailEpoch,id=String(route.params.gatewayId);loading.value=true;error.value='';gateway.value=undefined;try{const g=await api<Row>(`/api/v1/gateways/${enc(id)}`);const c=await api<Row>(`/api/v1/gateways/${enc(id)}/configuration`);let related:Row[]=[];if(canGateway('task:read',g))related=(await api<Page>(`/api/v1/tasks?gatewayId=${enc(id)}&limit=50`)).items;if(epoch!==detailEpoch||String(route.params.gatewayId)!==id)return;gateway.value=g;config.value=c;tasks.value=related}catch(e){if(epoch===detailEpoch)error.value=errorText(e)}finally{if(epoch===detailEpoch)loading.value=false}}

watch(()=>[route.meta.pageId,route.params.gatewayId,route.query.groupId],async()=>{listEpoch++;detailEpoch++;gateway.value=undefined;config.value=undefined;tasks.value=[];loading.value=true;if(pageId.value==='P02')filter.groupId=typeof route.query.groupId==='string'?route.query.groupId:'';try{await loadScopes()}catch(e){error.value=errorText(e)}if(pageId.value==='P02')await loadList();else await loadDetail()},{immediate:true})
function selectScope(data:Row){filter.groupId=data.kind==='GROUP'?data.scopeId:'';loadList()}
async function openEdit(g:Row){try{error.value='';const r=await apiResult<Row>(`/api/v1/gateways/${enc(g.gatewayId)}`);editId.value=g.gatewayId;editEtag.value=r.etag;Object.assign(editForm,{displayName:r.data.displayName||'',groupId:r.data.groupId||'',state:r.data.state});edit.value=true}catch(e){error.value=errorText(e)}}
async function saveEdit(){try{if(editForm.state==='RETIRED')await ElMessageBox.confirm('退役后不可恢复为活动状态，并会撤销设备接入凭据。','确认退役',{type:'warning'});saving.value=true;const body={...editForm};await api(`/api/v1/gateways/${enc(editId.value)}`,'PATCH',body,{etag:editEtag.value,key:formKey(body)});edit.value=false;ElMessage.success('网关信息已更新');await loadList()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{saving.value=false}}
async function importGateways(dryRun:boolean){try{if(!importForm.artifactId.trim())throw new Error('请输入已验证的设备清单制品 ID');if(!dryRun)await ElMessageBox.confirm('将依据签名清单登记设备。此操作不负责生产 Broker 开户。','确认导入',{type:'warning'});saving.value=true;const body:Row={artifactId:importForm.artifactId.trim(),dryRun};if(importForm.groupId)body.groupId=importForm.groupId;importResult.value=await api('/api/v1/gateway-imports','POST',body,{key:importKey(body)});if(!dryRun)await loadList()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{saving.value=false}}
const latestDiagnostic=computed(()=>tasks.value.find(t=>t.type==='DIAGNOSTICS'&&t.result))
</script>
<template><div class="gateway-pages">
 <el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/>
 <template v-if="pageId==='P02'"><header class="page-heading"><div><h1>网关设备</h1><p class="muted">设备身份、分组与接入状态</p></div><div><el-button v-if="can('gateway:write')" @click="importDialog=true;importResult=undefined">导入签名清单</el-button><el-button @click="loadList()">刷新</el-button></div></header>
 <div class="gateway-grid"><aside class="panel"><h3>资源范围</h3><el-button text @click="filter.groupId='';loadList()">全部可见网关</el-button><el-tree :data="tree" node-key="scopeId" :props="{label:'label',children:'children'}" default-expand-all highlight-current @node-click="selectScope"/><p class="muted">选择分组查询该组网关。项目节点返回全部可见记录。</p></aside><section class="panel">
 <div class="toolbar"><el-select v-model="filter.state" clearable placeholder="全部生命周期" @change="loadList()"><el-option v-for="s in ['UNCLAIMED','ACTIVE','DISABLED','RETIRED']" :key="s" :label="statusLabel(s)" :value="s"/></el-select><el-input v-model="filter.search" placeholder="本页检索：名称 / ID / SN / 型号" clearable/></div>
 <el-table :data="visibleRows" v-loading="loading" stripe @row-click="row=>router.push('/gateways/'+enc(row.gatewayId))" class="click-table"><el-table-column label="网关" min-width="190"><template #default="{row}"><strong>{{row.displayName||row.gatewayId}}</strong><div class="muted mono">{{row.gatewayId}}</div></template></el-table-column><el-table-column prop="sn" label="SN" min-width="130"/><el-table-column prop="model" label="型号" min-width="140"/><el-table-column label="版本" min-width="120"><template #default="{row}"><div>HW {{row.hardwareVersion}}</div><div class="muted">FW {{row.firmwareVersion||'未知'}}</div></template></el-table-column><el-table-column label="生命周期" min-width="100"><template #default="{row}"><el-tag>{{statusLabel(row.state)}}</el-tag></template></el-table-column><el-table-column label="接入" width="90"><template #default="{row}"><el-tag :type="row.online?'success':'info'">{{row.online?'在线':'离线'}}</el-tag></template></el-table-column><el-table-column label="最近上报" min-width="160"><template #default="{row}">{{dateTime(row.lastSeenAt)}}</template></el-table-column><el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><el-button v-if="canGateway('gateway:write',row)" link type="primary" @click.stop="openEdit(row)">编辑</el-button></template></el-table-column></el-table>
 <div class="toolbar footer"><span class="muted">已加载 {{rows.length}} 条 · 快照 {{dateTime(snapshot)}}</span><el-button :disabled="!next||loading" @click="loadList(true)">加载下一页</el-button></div></section></div>
 </template>
 <template v-else-if="gateway"><header class="page-heading"><div><el-button text @click="router.push('/gateways')">← 网关列表</el-button><h1>{{pageId==='P04'?'配置 · ':''}}{{gateway.displayName||gateway.gatewayId}}</h1><p class="muted">{{gateway.gatewayId}} · {{gateway.model}} · {{gateway.sn}}</p></div><div><el-tag :type="gateway.online?'success':'info'">{{gateway.online?'在线':'离线'}}</el-tag> <el-tag>{{statusLabel(gateway.state)}}</el-tag><el-button v-if="pageId!=='P04'" @click="loadDetail">刷新</el-button></div></header>
 <ConfigurationEditor v-if="pageId==='P04'" :gateway="gateway" class="panel"/>
 <div v-else class="detail-grid"><section class="panel"><el-tabs v-model="tab"><el-tab-pane label="概况" name="overview"><el-descriptions :column="2" border><el-descriptions-item label="型号">{{gateway.model}}</el-descriptions-item><el-descriptions-item label="SN">{{gateway.sn}}</el-descriptions-item><el-descriptions-item label="硬件版本">{{gateway.hardwareVersion}}</el-descriptions-item><el-descriptions-item label="固件版本">{{gateway.firmwareVersion||'未知'}}</el-descriptions-item><el-descriptions-item label="分组">{{scopes.find(s=>s.scopeId===gateway?.groupId)?.name||gateway.groupId}}</el-descriptions-item><el-descriptions-item label="最近上报">{{dateTime(gateway.lastSeenAt)}}</el-descriptions-item><el-descriptions-item label="期望配置版本">{{config?.desiredRevision}}</el-descriptions-item><el-descriptions-item label="已验证配置版本">{{config?.reportedRevision}}</el-descriptions-item></el-descriptions><el-alert title="在线状态只表示网关最近接入；设备操作是否生效请查看任务验证结果。" type="info" :closable="false" class="mt"/></el-tab-pane><el-tab-pane label="签名能力" name="capabilities"><div class="caps"><el-tag v-for="c in gateway.capabilities" :key="c">{{c}}</el-tag></div></el-tab-pane><el-tab-pane label="诊断结果" name="diagnostic"><template v-if="latestDiagnostic"><p>任务 <el-button link type="primary" @click="router.push('/tasks/'+latestDiagnostic.taskId)">{{latestDiagnostic.taskId}}</el-button> · {{dateTime(latestDiagnostic.result?.occurredAt)}}</p><pre>{{pretty(latestDiagnostic.result)}}</pre></template><el-empty v-else description="当前已加载任务中没有诊断结果"/></el-tab-pane><el-tab-pane label="关联任务" name="tasks"><el-table :data="tasks" @row-click="row=>router.push('/tasks/'+row.taskId)"><el-table-column prop="taskId" label="任务" min-width="180"/><el-table-column prop="type" label="类型"/><el-table-column label="状态"><template #default="{row}">{{statusLabel(row.state)}}</template></el-table-column><el-table-column label="创建时间" min-width="150"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column></el-table><el-button text @click="router.push({path:'/tasks',query:{gatewayId:gateway.gatewayId}})">查看全部任务</el-button></el-tab-pane></el-tabs></section>
 <aside class="panel action-panel"><h3>设备操作</h3><el-button v-if="canGateway('gateway:configure',gateway)" :disabled="!hasCapability(gateway,'CONFIGURE')" @click="router.push('/gateways/'+gateway.gatewayId+'/configuration')">配置网关</el-button><el-button v-if="canGateway('task:create',gateway)" @click="taskDialog=true">诊断 / 重启</el-button><el-button v-if="canGateway('gatt:read',gateway)" @click="router.push({path:'/gatt-connections',query:{gatewayId:gateway.gatewayId}})">蓝牙连接</el-button><el-button v-if="canGateway('firmware:deploy',gateway)" :disabled="!hasCapability(gateway,'FIRMWARE_UPGRADE')" @click="router.push({path:'/artifacts',query:{gatewayId:gateway.gatewayId}})">固件升级</el-button><el-button v-if="canGateway('data:read',gateway)" @click="router.push({path:'/events',query:{gatewayId:gateway.gatewayId}})">数据事件</el-button><p class="muted">能力以设备签名清单为准。物理执行不支持盲目重复。</p></aside></div>
 </template><el-skeleton v-else-if="loading" :rows="8" animated/><el-empty v-else description="网关不存在或无权查看"/>
 <el-drawer v-model="edit" title="修改网关" size="440px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="editForm.displayName" maxlength="100"/></el-form-item><el-form-item label="分组"><el-select v-model="editForm.groupId" filterable><el-option v-for="s in groupOptions" :key="s.scopeId" :label="s.name" :value="s.scopeId" :disabled="!can('gateway:write',s.scopeId)"/></el-select></el-form-item><el-form-item label="生命周期"><el-select v-model="editForm.state"><el-option v-for="s in ['ACTIVE','DISABLED','RETIRED']" :key="s" :label="statusLabel(s)" :value="s"/></el-select></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" :loading="saving" @click="saveEdit">保存修改</el-button></el-form></el-drawer>
 <el-dialog v-model="importDialog" title="导入签名设备清单" width="640px"><el-alert title="先在“固件与签名制品”上传已签名的 DEVICE_MANIFEST，再进行预检与导入。" type="info" :closable="false"/><el-form label-position="top"><el-form-item label="设备清单制品 ID"><el-input v-model="importForm.artifactId"/></el-form-item><el-form-item label="导入分组"><el-select v-model="importForm.groupId" clearable filterable><el-option v-for="s in groupOptions" :key="s.scopeId" :label="s.name" :value="s.scopeId" :disabled="!can('gateway:write',s.scopeId)"/></el-select></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><pre v-if="importResult">{{pretty(importResult)}}</pre><template #footer><el-button @click="router.push('/artifacts')">上传清单</el-button><el-button :loading="saving" @click="importGateways(true)">预检</el-button><el-button type="primary" :loading="saving" @click="importGateways(false)">正式导入</el-button></template></el-dialog>
 <el-dialog v-model="taskDialog" title="创建设备任务" width="560px" destroy-on-close><SimpleTaskForm v-if="gateway" :gateways="[gateway]" :gateway-id="gateway.gatewayId" @submitted="loadDetail"/></el-dialog>
 </div></template>
<style scoped>.gateway-grid{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px}.detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 240px;gap:20px}.page-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:22px}h1{margin:6px 0;font-size:26px}h3{margin:0 0 16px}.panel{padding:22px;border:1px solid #e2e8f0;border-radius:12px;background:white;min-width:0}.toolbar{display:flex;gap:12px;margin-bottom:16px}.toolbar .el-input{max-width:360px}.toolbar .el-select{width:170px}.footer{justify-content:space-between;align-items:center;margin:16px 0 0}.muted{color:#64748b;font-size:13px;line-height:1.6}.mono{font-family:monospace}.caps{display:flex;flex-wrap:wrap;gap:9px}.action-panel .el-button{display:flex;width:100%;margin:10px 0}.mb,.mt{margin:14px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:480px;overflow:auto;font-size:12px;line-height:1.6;background:#f5f7fa;padding:14px}.el-form .el-select{width:100%}.click-table :deep(.el-table__row){cursor:pointer}@media(max-width:1000px){.gateway-grid,.detail-grid{grid-template-columns:1fr}.page-heading{flex-wrap:wrap}}</style>
